const trvStorageDepartureId = 'public_site_departure_id'
const trvStorageCurrencyId = 'public_site_currency_id'
const trvCookieCountryId = 'public_site_country_id'
const trvCookieDepartureId = 'public_site_departure_id'
const tvPopularDepartureCookieName = 'tv-popular-departure'
const tvSearchCookieName = 'tv_search';
const tvSearchCookieOldName = 'tv-search';
const trvSearchCookieName = 'trv_search';
let trvIsSearchModuleBtnSearchHandled = false
const observerHandledItemClass = 'trv-observer-handled'
const trvDefaultCountryEnum = 'ru';

const trvHtmlBlocksCache = {};
let trvGlobalStatePromise = null;

loadCookieDeparture();

//GLOBAL STATE TAKE
trvLoadGlobalState();
//GLOBAL STATE TAKE END

let observer = new MutationObserver((mutationsList, observer) => {
    const searchFormModules = document.querySelectorAll('.tv-search-form');
    if(searchFormModules.length > 0){
        const cookieCurrencyId = trvGetTrvCookieCurrencyId();
        const cookieCountryId = trvGetTrvCookieCountryId();
        const { originId: countryOriginId } = trvGetCountryById(cookieCountryId) || {};
        let storageCurrencyId = localStorage.getItem(trvStorageCurrencyId)
        searchFormModules.forEach(searchFormModule => {
            if (!trvIsSearchModuleBtnSearchHandled && (searchFormModule.closest('.trv-search-p') && !searchFormModule.closest('.trv-search-hotels-p'))) {
                let btn = searchFormModule.querySelector('.TVSearchButton')
                if (btn) {
                    btn.addEventListener('click', () => {
                        _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'SEARCH'});
                    })
                    trvIsSearchModuleBtnSearchHandled = true
                }
            }
            if (!trvIsSearchModuleBtnSearchHandled && searchFormModule.closest('.trv-search-hotels-p')) {
                let btn = searchFormModule.querySelector('.TVSearchButton')
                if (btn) {
                    btn.addEventListener('click', () => {
                        _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'SEARCH_HOTEL'})
                    })
                    trvIsSearchModuleBtnSearchHandled = true
                }
            }
            if (!trvIsSearchModuleBtnSearchHandled && (searchFormModule.closest('.trv-b2c-main-p') || searchFormModule.closest('.trv-body--tours-page'))) {
                let btn = searchFormModule.querySelector('.TVSearchButton')
                if (btn) {
                    btn.addEventListener('click', () => {
                        _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'SEARCH'})
                    })
                    trvIsSearchModuleBtnSearchHandled = true
                }
            }
            if(countryOriginId) {
                if (searchFormModule.getAttribute('tv-origincountry') === null) {
                    searchFormModule.setAttribute('tv-origincountry', countryOriginId)
                }
            }
            if(cookieCurrencyId) {
                if (searchFormModule.getAttribute('tv-currency') === null) {
                    searchFormModule.setAttribute('tv-currency', cookieCurrencyId)
                }
            }
        })
    }

    const minPricesModules = document.querySelectorAll('.tv-min-price');
    if(minPricesModules.length > 0){
        // let storageDepartureId = localStorage.getItem(trvStorageDepartureId)
        const cookieCurrencyId = trvGetTrvCookieCurrencyId();
        minPricesModules.forEach(minPricesModule => {
            // if(storageDepartureId && trvGetCookie(trvCookieDepartureId) === null) {
                if (minPricesModule.getAttribute('tv-departure') === null) {
                    // minPricesModule.setAttribute('tv-departure', storageDepartureId)
                }
            // }
            if(cookieCurrencyId) {
                if (minPricesModule.getAttribute('tv-currency') === null) {
                    minPricesModule.setAttribute('tv-currency', cookieCurrencyId)
                }
            }
        })
    }

    const flightsModules = document.querySelectorAll('.tv-flights');
    if (flightsModules.length > 0) {
      flightsModules.forEach(flightsModule => {
          const cookieCurrencyId = trvGetTrvCookieCurrencyId();
          if (cookieCurrencyId) {
              if (flightsModule.getAttribute('tv-currency') === null) {
                  flightsModule.setAttribute('tv-currency', cookieCurrencyId)
              }
          }
      })
    }

    const statisticApps = document.querySelectorAll('#tvStatisticRoot');
    if (statisticApps) {
        const cookieCurrencyId = trvGetTrvCookieCurrencyId();
        statisticApps.forEach(appNode => {
            if(cookieCurrencyId) {
                if (appNode.getAttribute('tv-currency') === null) {
                    appNode.setAttribute('tv-currency', cookieCurrencyId)
                }
            }
        })
    }

    setTimeout(() => {
        observer.disconnect();
    }, 1000)
});

observer.observe(document, { childList: true, subtree: true });

// HOT TOURS PAGE OBSERVER
let observerHotToursPage = new MutationObserver((mutationsList, observer) => {
    const hotToursPageItems = document.querySelectorAll('.trv-hot-tours-p .trv-hot-tours-section__items')
    if (hotToursPageItems.length) {
        hotToursPageItems.forEach(hotToursItems => {
            let items = hotToursItems.querySelectorAll('.TVMinPriceTableItem:not(.'+observerHandledItemClass+')');
            [...items].filter(item => !item.classList.contains(observerHandledItemClass)).forEach(item => {
                item.addEventListener('click', () => {
                    if(typeof yaCounter5773432 !== "undefined" && typeof yaCounter5773432.reachGoal !== "undefined") {
                        yaCounter5773432.reachGoal('TOURSEARCH');
                    }
                    if(typeof _tmr !== "undefined" && typeof _tmr.push !== "undefined"){
                        _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'SEARCH'});
                    }
                })
                item.classList.add(observerHandledItemClass)
            })
        })
    }
});

observerHotToursPage.observe(document, { childList: true, subtree: true });
// HOT TOURS PAGE OBSERVER END

