                    _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'ADDTOCART'});
                }
            },
            {
                selector: '.TVTourCardInfo .TVTourCardAddToCart',
                action: () => {
                    _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'ADDTOCART'});
                }
            },
            {
                selector: '.TVToursCartRequest .TVRequestFormSendButton',
                action: (item) => {
                    let nameInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVNAME input')
                    let phoneInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVPHONE input')
                    let emailInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVEMAIL input')
                    if (nameInput && phoneInput && emailInput) {
                        if (nameInput.value !== '' && phoneInput.value !== '' && emailInput.value !== '') {
                            _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'HELPCART'});
                        }
                    }
                }
            },
            // {
            //     selector: '.TVRequestFormInfoBlock .TVRequestFormSendButton',
            //     action: (item) => {
            //         let nameInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVNAME input')
            //         let phoneInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVPHONE input')
            //         let emailInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVEMAIL input')
            //         if (nameInput && phoneInput && emailInput) {
            //             if (nameInput.value !== '' && phoneInput.value !== '' && emailInput.value !== '') {
            //                 _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'HELPCART'});
            //             }
            //         }
            //     }
            // },
            {
                selector: '.TVRequestWindow .TVRequestFormSendButton',
                action: (item) => {
                    let nameInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVNAME input')
                    let phoneInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVPHONE input')
                    let emailInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVEMAIL input')
                    if (nameInput && phoneInput && emailInput) {
                        if (nameInput.value !== '' && phoneInput.value !== '' && emailInput.value !== '') {
                            _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'HELPTOUR'});
                        }
                    }
                }
            },
            // {
            //     selector: '.TVRequestWindowContent .TVRequestFormSendButton',
            //     action: (item) => {
            //         let nameInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVNAME input')
            //         let phoneInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVPHONE input')
            //         let emailInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVEMAIL input')
            //         if (nameInput && phoneInput && emailInput) {
            //             if (nameInput.value !== '' && phoneInput.value !== '' && emailInput.value !== '') {
            //                 _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'NOTOUR'});
            //                 console.log('NOTOUR')
            //             }
            //         }
            //         console.log('NOTOUR', nameInput && phoneInput && emailInput)
            //         console.log('NOTOUR', nameInput.value)
            //     }
            // },
            {
                selector: '.TVTourBuyFromAgencyItemLink',
                action: (item) => {
                    _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'TOURREDIRECT'});
                }
            },
            {
                selector: '.TVTourBuyFromAgencyOfficeButton .TVButtonHover',
                action: (item) => {
                    _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'TOURREDIRECT'});
                }
            },
            {
                selector: '.TVTourCardWindow .TVRequestFormSendButton',
                action: (item) => {
                    let nameInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVNAME input')
                    let phoneInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVPHONE input')
                    let emailInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVEMAIL input')
                    if (nameInput && phoneInput && emailInput) {
                        if (nameInput.value !== '' && phoneInput.value !== '' && emailInput.value !== '') {
                            _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'ORDERTOUR'});
                        }
                    }
                }
            },
            {
                selector: '.TVMobilePanelBlock .TVRequestFormSendButton',
                action: (item) => {
                    let nameInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVNAME input')
                    let phoneInput = item.closest('.TVRequestFormPanel').querySelector('.TVUserFormInputs .TVPHONE input')
                    if (nameInput && phoneInput) {
                        if (nameInput.value !== '' && phoneInput.value !== '') {
                            _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'ORDERTOUR'});
                        }
                    }

                }
            },
            {
                selector: '.TVTourCardOperatorLinkBlock',
                action: (item) => {
                    _tmr.push({ type: 'reachGoal', id: 3331907, goal: 'TOURPARTNER'});
                }
            }
        ];

        const observerSearchModuleAddToCart = new MutationObserver((mutationsList, observer) => {
            observerTargetsData.forEach(({ selector, action }) => {
                let notHandledItems = [...document.querySelectorAll(selector)].filter(item => !item.classList.contains(observerHandledItemClass));
                if (notHandledItems.length) {
                    notHandledItems.forEach(item => {
                        item.addEventListener('click', (event) => {
                            action(item);
                            return true;
                        }, true);
                        item.classList.add(observerHandledItemClass);
                    });
                }
            });
        });

        observerSearchModuleAddToCart.observe(document, { childList: true, subtree: true });
    }

    //MAIN MENU
    if (document.querySelectorAll('.trv-menu li').length) {
        let lowerMenu = document.querySelector('.trv-header__lower');
        let parentCommonUl = document.querySelector('.trv-menu');
        let menuItems = document.querySelectorAll('.trv-menu li');
        let menuItemsLinks = document.querySelectorAll('.trv-menu li a');
        let submenuClass = 'trv-menu__submenu';
        let submenuActiveClass = 'trv-menu__submenu--active';
        let isAnySubmenuOpen = false;
        [...menuItems].filter(menuItem => menuItem.querySelectorAll('.'+submenuClass).length).forEach(menuItem => {
            menuItem.addEventListener('mouseover', function (e) {
                let itemCoords = this.getBoundingClientRect();
                let submenu = menuItem.querySelector('.trv-menu__submenu')
                submenu.style.top = itemCoords.top + itemCoords.height + 'px'
                document.querySelectorAll('.'+submenuClass).forEach(submenu => {
                    submenu.classList.remove(submenuActiveClass)
                })
                submenu.classList.add(submenuActiveClass)
                isAnySubmenuOpen = submenu
            })
        });
        [...menuItems].filter(menuItem => !menuItem.querySelectorAll('.'+submenuClass).length).forEach(menuItem => {
            menuItem.addEventListener('mouseover', function (e) {
                document.querySelectorAll('.'+submenuClass).forEach(submenu => {
                    submenu.classList.remove(submenuActiveClass)
                })
            })
        });
        document.addEventListener('mouseover', function (e) {
            if (e.target.closest('.trv-menu') === null){
                if (isAnySubmenuOpen) {
                    document.querySelectorAll('.'+submenuClass).forEach(submenu => {
                        submenu.classList.remove(submenuActiveClass)
                    })
                }
            }
        });
    }
    //MAIN MENU END

    //MOBILE MENU
    if (document.querySelectorAll('.trv-burger').length
        && document.querySelectorAll('.trv-mobile-menu').length
        && document.querySelectorAll('.trv-overlay').length
        && document.querySelectorAll('.trv-mobile-menu__close').length) {

        let burger = document.querySelector('.trv-burger');
        let mobileMenu = document.querySelector('.trv-mobile-menu');
        let mobileMenuActiveClass = 'trv-mobile-menu--active';
        let overlay = document.querySelector('.trv-overlay');
        let overlayActiveClass = 'trv-overlay--active';
        let closeBtn = document.querySelector('.trv-mobile-menu__close');

        burger.addEventListener('click', function(e) {
            e.preventDefault();
            trvOpenMobileMenu(mobileMenu, mobileMenuActiveClass, overlay, overlayActiveClass);
        })

        closeBtn.addEventListener('click', function(e) {
            e.preventDefault();
            trvCloseMobileMenu(mobileMenu, mobileMenuActiveClass, overlay, overlayActiveClass);
        })

        overlay.addEventListener('click', function(e) {
            e.preventDefault();
            trvCloseMobileMenu(mobileMenu, mobileMenuActiveClass, overlay, overlayActiveClass);
        })

    }
    let mobileMenuParentsClass = "trv-mobile-menu__menu-item--parent";
    if (document.querySelectorAll('.'+mobileMenuParentsClass).length) {
        let parentItems = document.querySelectorAll('.'+mobileMenuParentsClass)
        let parentActiveClass = 'trv-mobile-menu__menu-item--open'
        parentItems.forEach(parent => {
            let arrow = parent.querySelectorAll('.trv-mobile-menu__arrow')[0]
            let submenu = parent.querySelectorAll('.trv-mobile-menu__submenu')[0]
            if (typeof arrow !== 'undefined') {
                arrow.addEventListener('click', function (e) {
                    e.preventDefault()
                    if (!parent.classList.contains(parentActiveClass)) {
                        let submenuHeight = submenu.scrollHeight
                        submenu.style.height = submenuHeight + 'px'
                        parent.classList.add(parentActiveClass)
                    } else {
                        submenu.style.height = 0
                        parent.classList.remove(parentActiveClass)
                    }
                })
            }
        })
    }
    if (document.querySelectorAll('.trv-mobile-menu__tabs').length) {
        let menuNode = document.querySelector('.trv-mobile-menu');
        let menuWrapper = document.querySelector('.trv-mobile-menu--inner-wrapper');
        let tabsBlock = document.querySelector('.trv-mobile-menu__tabs')
        let tabs = tabsBlock.querySelectorAll('.trv-tab')
        let tabActiveClass = 'trv-tab--active'
        let activeTabKey = [...tabs].filter(tab => tab.classList.contains(tabActiveClass))[0].dataset.key
        let menusNav = document.querySelectorAll('.trv-mobile-menu-nav')
        let menuNavActiveClass = 'trv-mobile-menu-nav--active'
        let currentActiveMenuNavClass = 'trv-mobile-menu-nav--'+activeTabKey
        let activeMenuNav = [...menusNav].filter(nav => nav.classList.contains(currentActiveMenuNavClass))[0]
        let socials = document.querySelectorAll('.trv-mobile-menu__socials')
        let socialsActiveClass = 'trv-mobile-menu__socials--active'
        let currentActiveSocialsClass = 'trv-mobile-menu__socials--'+activeTabKey
        let activeSocials = [...socials].filter(soc => soc.classList.contains(currentActiveSocialsClass))[0]

        activeMenuNav.classList.add(menuNavActiveClass)
        activeSocials.classList.add(socialsActiveClass)

        {
            let allLinks = menuWrapper.getElementsByTagName("a");
            let issetInst = false;

            for (var i = 0; i < allLinks.length; i++) {
                let hrefValue = allLinks[i].getAttribute("href");

                if (hrefValue && hrefValue.toLowerCase().includes("instagram.com")) {
                    issetInst = true;
                }
            }
            if(!issetInst){
                let instSoc = `<a href="https://instagram.com/tourvisor_pro" target="_blank" class="trv-svg-icon trv-svg-icon--inst trv-soc--inst trv-svg-icon--loaded" rel="nofollow" title="Instagram">
                    <svg class="trv-svg-icon--inst" width="18" height="17" viewBox="0 0 18 17" fill="none">
                        <path d="M10.582 8.5C10.582 9.32515 9.91304 9.99414 9.08789 9.99414C8.26274 9.99414 7.59375 9.32515 7.59375 8.5C7.59375 7.67485 8.26274 7.00586 9.08789 7.00586C9.91304 7.00586 10.582 7.67485 10.582 8.5Z" fill="currentColor"></path>
                        <path d="M11.6112 3.98438H6.56433C5.46577 3.98438 4.57214 4.87801 4.57214 5.97656V11.0234C4.57214 12.122 5.46577 13.0156 6.56433 13.0156H11.6112C12.7098 13.0156 13.6034 12.122 13.6034 11.0234V5.97656C13.6034 4.87801 12.7098 3.98438 11.6112 3.98438ZM9.08777 10.9902C7.71464 10.9902 6.59753 9.87313 6.59753 8.5C6.59753 7.12687 7.71464 6.00977 9.08777 6.00977C10.4609 6.00977 11.578 7.12687 11.578 8.5C11.578 9.87313 10.4609 10.9902 9.08777 10.9902ZM11.9432 6.14258C11.6681 6.14258 11.4452 5.91962 11.4452 5.64453C11.4452 5.36944 11.6681 5.14648 11.9432 5.14648C12.2183 5.14648 12.4413 5.36944 12.4413 5.64453C12.4413 5.91962 12.2183 6.14258 11.9432 6.14258Z" fill="currentColor"></path>
                        <path d="M13.1055 0H5.07031C2.59875 0 0.587891 2.01086 0.587891 4.48242V12.5176C0.587891 14.9891 2.59875 17 5.07031 17H13.1055C15.577 17 17.5879 14.9891 17.5879 12.5176V4.48242C17.5879 2.01086 15.577 0 13.1055 0ZM14.5996 11.0234C14.5996 12.6711 13.259 14.0117 11.6113 14.0117H6.56445C4.91675 14.0117 3.57617 12.6711 3.57617 11.0234V5.97656C3.57617 4.32886 4.91675 2.98828 6.56445 2.98828H11.6113C13.259 2.98828 14.5996 4.32886 14.5996 5.97656V11.0234Z" fill="currentColor"></path>
                    </svg>
                </a>`;
                socials[1].insertAdjacentHTML('afterbegin', instSoc);
            }
            trvCheckVisibleElementsByCountry();
        }

        const tabKeys = [];
        tabs.forEach(tab => {
            let tabKey = tab.dataset.key
            tabKeys.push(tabKey);

            tab.addEventListener('click', function (e) {
                e.preventDefault()
                changeMenu(tabKey)
            })
        })

        function changeMenu(menuKey) {
            if (menuNode) {
                tabKeys.forEach(key => {
                    menuNode.classList.remove('trv-mobile-menu--'+key);
                })
                menuNode.classList.add('trv-mobile-menu--'+menuKey);
            }

            tabs.forEach(tab => tab.classList.remove(tabActiveClass));
            [...tabs].filter(tab => tab.dataset.key === menuKey)[0].classList.add(tabActiveClass)


            currentActiveMenuNavClass = 'trv-mobile-menu-nav--'+menuKey
            currentActiveSocialsClass = 'trv-mobile-menu__socials--'+menuKey

            menusNav.forEach(menu => menu.classList.remove(menuNavActiveClass));
            [...menusNav].filter(menu => menu.classList.contains(currentActiveMenuNavClass))[0].classList.add(menuNavActiveClass);

            socials.forEach(soc => soc.classList.remove(socialsActiveClass));
            [...socials].filter(soc => soc.classList.contains(currentActiveSocialsClass))[0].classList.add(socialsActiveClass);
        }
    }
    //MOBILE MENU END

    //PAGE CONTENT

    //page class manipulation
    let pageClasses = ["trv-search-p", "trv-hot-tours-p", "trv-tour-statistic-p", "trv-countries-hotels-p"];
    let pageContentWrapper = document.querySelector('.trv-page-content');
    let mainDocumentBlock = document.querySelector('.trv-main');
    pageClasses.forEach(pClass => {
        let el = document.querySelector('.'+pClass);

        if (el) {
            // el.classList.remove(pClass);
            pageContentWrapper.classList.add(pClass);
            mainDocumentBlock.classList.add(pClass+'--main');
        }
    })
    //page class manipulation end

    //PAGE CONTENT END

    // SEARCH FORM MODULE
    {
        const trvSearchFormModuleSearchLink = trvGlobalLinks.find((item) => item.name === "b2c_search")?.value;
        const trvSearchFormModuleSearchHotelsLink = trvGlobalLinks.find((item) => item.name === "b2c_search_hotels")?.value;

        const isEnabledRadioLinks =
            window.location.pathname === "/" ||
            window.location.pathname === "/" + trvSearchFormModuleSearchLink ||
            window.location.pathname === "/" + trvSearchFormModuleSearchHotelsLink;

        function addSwitchListener(radio, url, params = {}) {
            if (radio) {
                const newRadio = radio.cloneNode(true);
                radio.replaceWith(newRadio);
                newRadio.addEventListener("click", () => {
                    const searchParams = new URLSearchParams(params).toString();
                    const fullUrl = searchParams ? url + (url.includes("?") ? "&" : "?") + searchParams : url;
                    location.href = fullUrl;
                });
            }
        }

        if (
            isEnabledRadioLinks &&
            (document.querySelector(".trv-search-p") || document.querySelector(".trv-b2c-main-p")) &&
            document.querySelector(".tv-search-form")
        ) {
            const observer = new MutationObserver(() => {
                const searchForm = document.querySelector(".tv-search-form");
                if (!searchForm) return;

                let radioInputs = searchForm.querySelectorAll(".TVToggleSwitchItems .TVToggleSwitchItem");

                if (!radioInputs.length) {
                    radioInputs = searchForm.querySelectorAll(".TVSearchModeControl .TVInputRadio");
                }

                if (radioInputs.length) {
                    const currentURL = window.location.pathname;

                    if (currentURL === "/" + trvSearchFormModuleSearchLink || currentURL === "/") {
                        // Клик по "Отели"
                        addSwitchListener(radioInputs[1], trvSearchFormModuleSearchHotelsLink);
                    }

                    if (currentURL === "/" + trvSearchFormModuleSearchHotelsLink) {
                        // Клик по "Поиск" и "Горящие"
                        addSwitchListener(radioInputs[0], trvSearchFormModuleSearchLink);
                        addSwitchListener(radioInputs[2], trvSearchFormModuleSearchLink, {
                            ts_dosearch: 0,
                            s_form_mode: 3,
                        });
                    }

                    observer.disconnect();
                }
