function trvSvgSpritesLoad() {
    if (document.querySelectorAll('.trv-svg-icon').length) {
        let iconElems = document.querySelectorAll('.trv-svg-icon');
        let sprites = document.querySelectorAll('.trv-svg-sprites symbol');

        [...iconElems].filter(elem => !elem.classList.contains('trv-svg-icon--loaded')).forEach(elem => {
            let elemClasses = elem.classList;
            let svgIcon = null;
            let svgIconWrapper = null;

            elemClasses.forEach(elemClass => {
                let needableSprite = [...sprites].filter(sprite => sprite.classList.contains(elemClass));
                if (needableSprite.length) {
                    let spriteAttributes = needableSprite[0].attributes;
                    let svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
                    Object.values(spriteAttributes).forEach(attr => {
                        if (attr.name !== 'id') {
                            svg.setAttribute(attr.name, attr.value)
                        }
                    })
                    svgIcon = needableSprite[0].cloneNode(true);
                    svg.innerHTML = svgIcon.innerHTML;
                    svgIcon = svg;
                }
            })

            if (elem && svgIcon) {
                if (svgIcon.classList.contains('trv-svg-icon--qa-plus-minus')) {
                    svgIconWrapper = document.createElement('div');
                    svgIconWrapper.classList.add('trv-svg-icon-wrapper');
                    svgIconWrapper.appendChild(svgIcon);
                    svgIcon = svgIconWrapper;
                }

                elem.insertAdjacentElement('afterbegin', svgIcon);
                elem.classList.add('trv-svg-icon--loaded');
            }


        })

    }
}
