//SVG PREPARE
function trvSvgSpritesPrepare() {
    let spritesBlock = document.querySelector('.trv-svg-sprites');
    let svgBlockClass = ".trv-svg-sprites--img";
    let svgsDiv = document.querySelectorAll(svgBlockClass + ' > div');

    svgsDiv.forEach(svgDiv => {

        toSVG(svgDiv.querySelector('img'), {
            svgClass: "prepared",
            onComplete: function() {
                replaceSvgToSymbol(svgDiv);
            }});

        // svgDiv.querySelector('img').toSVG({
        //     svgClass: "prepared",
        //     onComplete: function() {
        //         replaceSvgToSymbol(svgDiv);
        //     }
        // });

    })

    function replaceSvgToSymbol(block){

        let svgs = document.querySelectorAll(svgBlockClass + ' .prepared');

        svgs.forEach(svg => {

            let svgAttributes = svg.attributes;

            let symbol = document.createElementNS("http://www.w3.org/2000/svg", "symbol");

            Object.values(svgAttributes).forEach(attr => {
                if (attr.name !== 'id') {
                    symbol.setAttribute(attr.name, attr.value)
                }
            })

            symbol.id = block.id;

            svgClone = svg.cloneNode(true);

            symbol.innerHTML = svg.innerHTML;

            symbol.querySelectorAll('path').forEach(path => {
                path.setAttribute('fill', 'currentColor');
            })

            spritesBlock.append(symbol);
            svg.closest('div').remove();

            refreshSvgUse();
        })

    }

    function refreshSvgUse(){
        let svgUses = document.querySelectorAll('use');

        svgUses.forEach(use => {
            let newSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg'),
                newUse = document.createElementNS('http://www.w3.org/2000/svg', 'use');
            let curSvg = use.closest('svg'),
                curSvgAttributes = curSvg.attributes;

            newUse.setAttributeNS('http://www.w3.org/1999/xlink', 'xlink:href', use.href.baseVal);

            newSvg.appendChild(newUse);

            Object.values(curSvgAttributes).forEach(attr => {
                if (attr.name !== 'id') {
                    newSvg.setAttribute(attr.name, attr.value)
                }
            })

            curSvg.replaceWith(newSvg);
        })

    }

}
//SVG PREPARE END

//https://github.com/multum/img-to-svg
toSVG = function (el, obj) {
    var defaultObj = {
        svgClass: "replaced-svg",
        onComplete: function() {

        },
    }

    function extend(one, two) {
        if (typeof two != "object") return false;
        for (var key in one) {
            if (two.hasOwnProperty(key)) break;
            two[key] = one[key];
        }
        return two;
    }

    var params = extend(defaultObj, obj);

    var getSVG = function(file, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open('GET', file, true);
        xhr.send(); // (1)
        xhr.onreadystatechange = function() { // (3)
            if (xhr.readyState != 4) return;
            if (xhr.status != 200) {
                console.log((xhr.status + ': ' + xhr.statusText));
            } else {
                callback.call(this, xhr.responseText)
            }
        }
    }

    // Array.prototype.forEach.call(document.querySelectorAll(this), function(el) {
    // var el = this;
    var img = el;
    var imgID = img.getAttribute('id');
    var imgClass = img.getAttribute('class');
    var imgURL = img.getAttribute('src');
    if (!(/\.(svg)$/i.test(imgURL))) {
        console.warn("image src='" + imgURL + "' is not a SVG, item remained tag <img/> ");
        return;
    }
    getSVG(imgURL, function(data) {
        var html = document.createElement("html");
        html.innerHTML = "<body>" + data + "</body>"
        var svg = html.getElementsByTagName("svg")[0];
        if (imgID != undefined && imgID != null) {
            svg.setAttribute('id', imgID);
        }
        if (typeof imgClass !== 'undefined') {
            svg.setAttribute('class', imgClass + " " + params.svgClass);
        }
        svg.removeAttribute('xmlns:a');
        if (!svg.getAttribute('viewBox') && svg.getAttribute('height') && svg.getAttribute('width')) {
            svg.getAttribute('viewBox', '0 0 ' + svg.getAttribute('height') + ' ' + svg.getAttribute('width'))
        }
        img.parentNode.replaceChild(svg, img);
        typeof params.onComplete == "function" ? params.onComplete.call(this, svg) : '';
    })
    // });
}

class BodyScroll {
    constructor() {
        this.isDisabled = false;
        this.scrollTop = 0;
    }

    get isMobile() {
        if (
            /Android|webOS|iPhone|iPad|iPod|BlackBerry|BB|PlayBook|IEMobile|Windows Phone|Kindle|Silk|Opera Mini/i.test(
                navigator.userAgent
            )
        ) {
            return true;
        }

        return false;
    }

    _getScrollBarWidth() {
        return window.innerWidth - document.body.clientWidth;
    }

    disable(disableMargin = false) {
        this.isDisabled = true;
        this.scrollTop = window.pageYOffset;

        const scrollbarWidth = this._getScrollBarWidth();

        /**
         * Для фикса бага на safari 15
         * @see https://stackoverflow.com/questions/69589924/ios-15-minimized-address-bar-issue-with-fixed-position-full-screen-content
         */
        document.documentElement.style.height = '100vh';

        document.body.style.position = 'fixed';
        if (!disableMargin) {
            document.body.style.marginTop = -this.scrollTop + 'px';
        }
        document.body.style.width = '100%';
        document.body.style.overflowY =
            scrollbarWidth && !this.isMobile ? 'scroll' : '';
    }

    enable(disableMargin = false) {
        this.isDisabled = false;
        document.documentElement.style.height = '';
        document.body.style.position = '';
        if (!disableMargin) {
            document.body.style.marginTop = '';
        }
        document.body.style.width = '';
        document.body.style.overflowY = '';

        window.scrollTo(0, this.scrollTop);
    }
}

