//GLOBAL STATE
function trvRequestGlobalState(callback) {
    if (!trvGlobalStatePromise) {
        trvGlobalStatePromise = new Promise((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            const url = '/templates/tourvisor/includes/variables/trv_global_state.php';

            xhr.onreadystatechange = function () {
                if (xhr.readyState !== 4) {
                    return;
                }

                if (xhr.status !== 200) {
                    reject(`Error: ${xhr.status}`);
                    return;
                }

                try {
                    const response = JSON.parse(xhr.responseText);

                    if (typeof response === 'undefined') {
                        reject('Response is undefined');
                        return;
                    }

                    resolve(response);
                } catch {
                    reject('Invalid JSON response');
                }
            };

            xhr.open('POST', url, true);
            xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            xhr.send('trv_get_global_state=true');
        }).catch((error) => {
            trvGlobalStatePromise = null;
            throw error;
        });
    }

    trvGlobalStatePromise.then(
        (response) => callback(null, response),
        (error) => callback(error),
    );
}

function trvLoadGlobalState() {
    trvRequestGlobalState((error, response) => {
        if (!error) {
            window.trvGlobalState = response;
        } else {
            console.error(error);
        }
    });
}

function trvFetchGlobalState() {
    return new Promise((resolve, reject) => {
        trvRequestGlobalState((error, response) => {
            if (!error) {
                resolve(response);
            } else {
                reject(error);
            }
        });
    });
}

async function trvGetGlobalStateCountries() {
    const objectKey = 'country';
    let globalState = window?.trvGlobalState;
    if (!globalState || !globalState[objectKey]) {
        globalState = await trvFetchGlobalState()
    }

    if (!globalState || !globalState[objectKey]) {
        return [];
    }

    return globalState[objectKey];
}
//GLOBAL STATE END

function trvGetCookie(name) {
    const cookies = document.cookie.split('; ');
    for (const cookie of cookies) {
        const [cookieName, cookieValue] = cookie.split('=');
        if (cookieName === name) {
            return cookieValue;
        }
    }
    return null;
}

function loadCookieDeparture() {
    let cityId = trvGetCookie(trvCookieDepartureId);
    let blocksReady = -1;
    if (cityId !== null) {
        const selectorsToWaitFor = [
            '.tv-search-form',
            '.tv-min-price',
        ];

        function handleMutations(mutationsList, observer) {
            for (let mutation of mutationsList) {
                if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
                    for (let node of mutation.addedNodes) {
                        for (let selector of selectorsToWaitFor) {
                            if (node instanceof Element && node.matches(selector)) {
                                // node.setAttribute('tv-departure', cityId.toString());
                                blocksReady++;
                                break;
                            }
                        }
                    }
                }
            }

            if (blocksReady == selectorsToWaitFor.length) {
                observer.disconnect();
            }
        }

        // Создаем MutationObserver
        const observer = new MutationObserver(handleMutations);

        // Наблюдаем за изменениями в body
        observer.observe(document, { childList: true, subtree: true });
    }
}

