function trvHistoryBlockRefresh(cityId = null) {
    const blocks = document.querySelectorAll('.trv-search-history')
    let apiLink = "https://tourvisor.ru/includes/tourlinksdep.php";
    if (cityId !== null) {
        apiLink += "?departure="+cityId;
    }

    const xhr = new XMLHttpRequest();

    xhr.open('GET', apiLink, true);

    xhr.responseType = "document";

    xhr.onload = function () {
        if (xhr.status >= 200 && xhr.status < 300) {
            if (xhr !== null && xhr.response !== null) {
                const response = xhr.response.documentElement;
                const responseBody = response.querySelector('body');
                const responseItems = response.querySelector('.trv-search-history__items');
                if (responseItems) {
                    blocks.forEach(block => {
                        const innerWrapper = block.querySelector('.trv-search-history__inner-wrapper')
                        innerWrapper.innerHTML = responseBody.innerHTML

                        if (document.querySelectorAll('.trv-search-history__swiper').length) {
                            const searchHistorySwiper = new Swiper('.trv-search-history__swiper', {
                                // Optional parameters
                                direction: 'horizontal',
                                loop: false,
                                slidesPerView: 'auto',
                                spaceBetween: 20,

                                navigation: {
                                    nextEl: block.querySelector('.trv-search-history__swiper-button-next'),
                                    prevEl: block.querySelector('.trv-search-history__swiper-button-prev'),
                                },
                            });
                            trvSvgSpritesLoad();
                        }
                    })
                } else {
                    reset()
                }
            }else{
                reset()
            }
        } else {
            console.error('Ошибка при выполнении запроса: ' + xhr.status);
        }
    };

    xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

    xhr.send();

    function reset() {
        blocks.forEach(block => {
            const innerWrapper = block.querySelector('.trv-search-history__inner-wrapper')
            innerWrapper.innerHTML = "";
        })
    }
}

async function trvCheckVisibleElementsByCountryCustomSelectors(currentCountryId) {
    const kzId = await trvGetCountryIdByEnum('kz');
    const uzId = await trvGetCountryIdByEnum('uz');
    const kgId = await trvGetCountryIdByEnum('kg');
    const selectors = [
        { selector: '.trv-soc--inst', id: [kzId, uzId, kgId] },
    ];

    const handledClass = 'trv-partial-invisible';

    selectors.forEach(selectorData => {
        const { selector, id = [], outId } = selectorData;
        const elements = document.querySelectorAll(selector);

        elements.forEach(element => {
            const shouldShowElement = id.includes(parseInt(currentCountryId)) ||
                (outId && !outId.includes(parseInt(currentCountryId)));

            if (!shouldShowElement) {
                element.classList.add(handledClass);
            } else {
                element.classList.remove(handledClass);
            }

            if (element.classList.contains(handledClass)) {
                element.remove();
            }
        });
    });
}

