        try {
            const countryAttr = element.getAttribute('data-country');
            if (countryAttr) {
                countryEnums = JSON.parse(countryAttr);
            }
        } catch (error) {
            console.warn('Ошибка при парсинге data-country:', error);
            countryEnums = [];
        }

        try {
            const excludedCountryAttr = element.getAttribute('data-excluded-country');
            if (excludedCountryAttr) {
                excludedCountryEnums = JSON.parse(excludedCountryAttr);
            }
        } catch (error) {
            console.warn('Ошибка при парсинге data-excluded-country:', error);
            excludedCountryEnums = [];
        }

        const countryIds = await Promise.all(countryEnums.map(enumValue => trvGetCountryIdByEnum(enumValue)));
        const excludedCountryIds = await Promise.all(excludedCountryEnums.map(enumValue => trvGetCountryIdByEnum(enumValue)));

        const shouldShowElement =
            (countryIds.length > 0 && countryIds.includes(currentCountryId)) ||
            (countryIds.length === 0 && !excludedCountryIds.includes(currentCountryId));

        if (!shouldShowElement) {
            element.classList.add(handledClass);
        } else {
            element.classList.remove(handledClass);
        }

        if (element.classList.contains(handledClass)) {
            element.remove();
        }

        element.removeAttribute('data-country');
        element.removeAttribute('data-excluded-country');
    }
}

