async function trvGetFileContent(filePath, data = {}) {
    try {
        const response = await fetch(filePath);

        if (!response.ok) {
            throw new Error(`Ошибка при загрузке файла: ${response.statusText}`);
        }

        const content = await response.text();

        const parser = new DOMParser();
        const doc = parser.parseFromString(content, 'text/html');

        const styleBlocks = doc.querySelectorAll('style');
        if (styleBlocks.length > 0) {
            styleBlocks.forEach(styleBlock => {
                document.head.appendChild(styleBlock);
            });
        }

        let htmlContent = doc.body.innerHTML;

        for (const [key, value] of Object.entries(data)) {
            const placeholder = new RegExp(`{{${key}}}`, 'g');
            htmlContent = htmlContent.replace(placeholder, value);
        }

        return htmlContent;

    } catch (error) {
        console.error('Ошибка:', error);
        throw error;
    }
}

function trvObserveTVSearchResultItem(resItem) {
    const observer = new MutationObserver((mutationsList) => {
        for (let mutation of mutationsList) {
            if (mutation.type === 'childList') {
                const children = resItem.children;
                if (children.length > 6) {
                    for (let i = 6; i < children.length; i++) {
                        children[i].addEventListener('click', trvHandleClickTVSearchResultItem, true);
                    }
                }
            }
        }
    });

    const config = { childList: true };
    observer.observe(resItem, config);
}

