    iconClose.setAttribute("viewBox", "0 0 11 11");
    iconClose.insertAdjacentHTML('afterbegin', '<path fill-rule="evenodd" clip-rule="evenodd" d="M10.5293 1.53033C10.8222 1.23744 10.8222 0.762563 10.5293 0.46967C10.2364 0.176777 9.76156 0.176777 9.46867 0.46967L5.49901 4.43933L1.52935 0.46967C1.23646 0.176777 0.761587 0.176777 0.468693 0.46967C0.1758 0.762563 0.1758 1.23744 0.468693 1.53033L4.43835 5.49999L0.468693 9.46965C0.1758 9.76254 0.1758 10.2374 0.468693 10.5303C0.761587 10.8232 1.23646 10.8232 1.52935 10.5303L5.49901 6.56065L9.46867 10.5303C9.76156 10.8232 10.2364 10.8232 10.5293 10.5303C10.8222 10.2374 10.8222 9.76254 10.5293 9.46965L6.55967 5.49999L10.5293 1.53033Z" fill="#2B3F5A"/>')
    closeDiv.appendChild(iconClose)

    block.classList.add('trv-modal')
    block.appendChild(closeDiv)
    document.body.appendChild(block)

    block.addEventListener('click', function (e) {
        if (typeof config.closeCallback === 'function') {
            config.closeCallback();
        }
        block.classList.remove('trv-modal--active')
        if (!block.dataset.scrollWasDisabled) {
            bdScroll.enable();
        }
        setTimeout(() => {
            block.remove()
        }, 300)
    })

    return block;
}

function trvOpenModalBlock(config = {}) {
    let modal = document.querySelector('.trv-modal')
    let modalActiveClass = "trv-modal--active"
    let modalCloseDiv = modal.querySelector('.trv-modal__close')
    let video = null
    let videoCoords = null
    let wwidth = window.outerWidth

    if (typeof bdScroll === 'undefined') {
        bdScroll = new BodyScroll;
    }

    if (modal.querySelectorAll('video').length) {
        video = modal.querySelector('video')
        videoCoords = video.getBoundingClientRect()
    }

    if (config.closeIcon !== false) {
        setCloseIcon()
    }

    function setCloseIcon() {
        let checkActive = setInterval(function() {
            if (modal.classList.contains(modalActiveClass)) {
                let innerDiv = modal.querySelectorAll(':scope > *:not(.trv-modal__close)')[0]
                if (typeof innerDiv !== 'undefined') {
                    innerDivCoords = innerDiv.getBoundingClientRect()

                    modalCloseDiv.classList.add('trv-modal__close--active')
                    if (wwidth < 768) {
                        modalCloseDiv.style.setProperty('--posTop', parseInt(innerDivCoords.top) - 60 + 'px')
                        modalCloseDiv.style.setProperty('--posLeft', parseInt(innerDivCoords.left) + parseInt(innerDivCoords.width) - (modalCloseDiv.getBoundingClientRect().width - 15) + 'px')
                    } else {
                        modalCloseDiv.style.setProperty('--posTop', parseInt(innerDivCoords.top) - 40 + 'px')
                        modalCloseDiv.style.setProperty('--posLeft', parseInt(innerDivCoords.left) + parseInt(innerDivCoords.width) + 30 + 'px')
                    }
                    clearInterval(checkActive)
                }
            }
        }, 300)

        setTimeout(() => {
            if (typeof checkActive !== 'undefined') {
                clearInterval(checkActive)
            }
        }, 5000)
    }

    function closeModal() {
        modal.classList.remove(modalActiveClass)
    }

    modal.querySelectorAll(':scope > *:not(.trv-modal__close)').forEach(div => {
        div.addEventListener('click', function (e) {
            e.stopPropagation()
        })
    })

    const scrollAlreadyDisabled = bdScroll.isDisabled;
    if (scrollAlreadyDisabled) {
        modal.dataset.scrollWasDisabled = 'true';
    }

    bdScroll.disable()
    modal.classList.add(modalActiveClass)

    return modal
}

function trvCloseModalBlock() {
    let modal = document.querySelector('.trv-modal')
    let modalActiveClass = "trv-modal--active"

    if (!modal.dataset.scrollWasDisabled) {
        bdScroll.enable();
    }
    modal.classList.remove('trv-modal--active');
    setTimeout(() => {
        modal.remove()
    }, 300)
}

