function trvGetTrvCookie() {
    const data = trvGetCookie(trvSearchCookieName);
    return data ? JSON.parse(decodeURIComponent(data)) : null;
}

function trvSetTrvCookie(data) {
    const jsonData = JSON.stringify(data);
    const encodedData = encodeURIComponent(jsonData);
    const expires = trvGetTvCookieExpireDate();
    const path = trvGetTvCookiePath();

    document.cookie = `${trvSearchCookieName}=${encodedData}; expires=${expires}; path=${path}`;
}

function trvGetTrvCookieCurrencyId() {
    const cookieData = trvGetTrvCookie();
    const { currencyId } = cookieData || {};
    return currencyId || 0;
}

function trvGetTrvCookieCountryId() {
    const cookieData = trvGetTrvCookie();
    const { countryId } = cookieData || {};
    return countryId || 0;
}

function trvUpdateTrvCookieCountryId(countryId) {
    const prevData = trvGetTrvCookie();
    const resultData = {...prevData, countryId};
    trvSetTrvCookie(resultData);
}

function trvUpdateTrvCookieCurrencyId(currencyId) {
    const prevData = trvGetTrvCookie();
    const resultData = {...prevData, currencyId};
    trvSetTrvCookie(resultData);
}
