//TV COOKIE
function trvGetTvCookie(cookieName) {
    const data = trvGetCookie(cookieName);
    return data ? JSON.parse(decodeURIComponent(data)) : null;
}

function trvSetTvCookie(cookieName, data) {
    const jsonData = JSON.stringify(data);
    const encodedData = encodeURIComponent(jsonData);
    const expires = trvGetTvCookieExpireDate();
    const path = trvGetTvCookiePath();

    document.cookie = `${cookieName}=${encodedData}; expires=${expires}; path=${path}`;
}

function trvGetTvCookieExpireDate() {
    const date = new Date();
    date.setDate(date.getDate() + 30);
    return date.toUTCString();
}

function trvGetTvCookiePath() {
    return '/';
}
