function trvUpdateTvSearchDepartureCookie(departureId) {
    const currentData = trvGetTvCookie(tvSearchCookieName);
    const newData = {...currentData, Departure: Number(departureId)};
    trvSetTvCookie(tvSearchCookieName, newData);
    trvUpdateTvSearchDepartureOldCookie(departureId);
}

function trvGetTvSearchDepartureIdCookie() {
