async function trvGetCountryIdByEnum(enumValue) {
    const objectEnumsKey = 'enums';
    const objectCountryIdKey = 'countryId';
    let globalState = window?.trvGlobalState;
    if (!globalState || !globalState[objectEnumsKey] || !globalState[objectEnumsKey][objectCountryIdKey]) {
        globalState = await trvFetchGlobalState()
    }

    if (!globalState || !globalState[objectEnumsKey] || !globalState[objectEnumsKey][objectCountryIdKey]) {
        return null;
    }

    return globalState[objectEnumsKey][objectCountryIdKey][enumValue] || 0;
}

async function trvGetCountryByEnum(enumValue) {
    const countryId = await trvGetCountryIdByEnum(enumValue);
    const globalState = window?.trvGlobalState;
    if (!countryId || !globalState || !globalState['country']) {
        return;
    }

    return globalState['country'].find(item => item.id === countryId) || null;
}

function trvGetCountryById(countryId) {
    const globalState = window?.trvGlobalState;
    if (!countryId || !globalState || !globalState['country']) {
        return;
    }

    return globalState['country'].find(item => item.id === countryId) || null;
}
